public class RequestTracker {
    private volatile long lastRequestTimestamp = 0L;  // Atomic 64-bit access
    private volatile double averageResponseTime = 0.0;  // Atomic 64-bit access

    // Called by multiple request handler threads
    public void recordRequest(long timestamp, double responseMs) {
        lastRequestTimestamp = timestamp;  // Atomic write, visible to all
        averageResponseTime = responseMs;  // Atomic write, visible to all
    }

    // Called by monitoring thread
    public String getStats() {
        var timestamp = lastRequestTimestamp;  // Atomic read
        var avgTime = averageResponseTime;     // Atomic read
        return String.format("Last request: %d, Avg response: %.2f ms", 
                           timestamp, avgTime);
    }
}
